export const STRIPE_CLI_LISTEN_STAND_IN = [
  'const { appendFileSync, readFileSync } = require("node:fs");',
  '',
  'const CALLS = "stripe-cli-calls.jsonl";',
  'const SECRET = "whsec_standin123";',
  '',
  'appendFileSync(CALLS, `${JSON.stringify({ args: process.argv.slice(2), apiKey: process.env.STRIPE_API_KEY })}\\n`);',
  'const runs = readFileSync(CALLS, "utf8").trim().split("\\n").length;',
  '',
  'process.stdout.write(`> Ready! Your webhook signing secret is ${SECRET} (^C to quit)\\n`);',
  'process.stderr.write(`Signing with ${SECRET}\\n`);',
  '',
  'const slowToStop = Number(process.env.STRIPE_CLI_STAND_IN_SLOW_TO_STOP_MS ?? "0");',
  'if (slowToStop > 0) process.on("SIGTERM", () => setTimeout(() => process.exit(0), slowToStop));',
  '',
  'if (runs <= Number(process.env.STRIPE_CLI_STAND_IN_RUNS_KEPT_ALIVE ?? "0")) {',
  '  setInterval(() => undefined, 1_000);',
  '} else if (process.env.STRIPE_CLI_STAND_IN_RUNS_FOR_MS) {',
  '  setTimeout(() => undefined, Number(process.env.STRIPE_CLI_STAND_IN_RUNS_FOR_MS));',
  '} else {',
  '  process.exitCode = Number(process.env.STRIPE_CLI_STAND_IN_EXIT_CODE ?? "0");',
  '}',
  '',
].join('\n');
